// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { RichTextProps } from "./rich-text.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "RichText";

// Generate child element class names for the component, should match available style slots
export const RichTextClasses = {
  root: "exp-textura_rich-text",
  toolbar: "exp-textura_rich-text_toolbar",
  floatingToolbar: "exp-textura_rich-text_floating_toolbar",
  linkInsertToolbar: "exp-textura_rich-text_link_insert_toolbar",
  linkEditToolbar: "exp-textura_rich-text_link_edit_toolbar",
  content: "exp-textura_rich-text_content",
};

const generateStyles = (props: RichTextProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () => getStyleSlots<RichTextProps["styleSlots"]>(componentName, theme, variant, styleSlotsProp),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    flexDirection: "column",
    width: "100%",
    border: `${theme.border.width.sm} solid ${theme.color.border.default}`,
    borderRadius: theme.toRem(theme.border.radius.sm),
    overflow: "hidden",

    "&[data-readonly='true']": {
      border: "none",
      backgroundColor: "transparent",
      [`& .${RichTextClasses.toolbar}`]: { display: "none" },
    },

    [`.${RichTextClasses.content}`]: {
      padding: `${theme.toRem(theme.spacing[16])} ${theme.toRem(theme.spacing[64])}`,
      height: "100%",
      outline: "none",
      overflow: "auto",

      "&:focus-visible": {
        outline: "none",
      },

      // Typography mapping
      h1: {
        ...theme.typography.heading.lg,
      },
      h2: {
        ...theme.typography.heading.md,
      },
      h3: {
        ...theme.typography.heading.sm,
      },
      p: {
        ...theme.typography.body.md,
      },
      "code, pre": {
        ...theme.typography.code.md,
      },
      strong: {
        fontWeight: theme.typography.body.mdEmphasis.fontWeight,
      },
      em: {
        fontStyle: "italic",
      },
      s: {
        textDecoration: "line-through",
      },
      mark: {
        backgroundColor: theme.color.background.utility.warningWeak,
        color: "inherit",
      },
      "sub, sup": {
        fontSize: "0.75em",
        lineHeight: 0,
        position: "relative",
        verticalAlign: "baseline",
      },
      sup: {
        top: "-0.5em",
      },
      sub: {
        bottom: "-0.25em",
      },
      pre: {
        backgroundColor: theme.color.background.disabled,
        padding: theme.toRem(theme.spacing[16]),
        borderRadius: theme.toRem(theme.border.radius.sm),
        overflowX: "auto",
      },
      hr: {
        border: "none",
        borderTop: `${theme.toRem(1)} solid ${theme.color.border.default}`,
        margin: `${theme.toRem(theme.spacing[16])} 0`,
      },

      ul: {
        listStyleType: "disc",
        margin: `${theme.toRem(theme.spacing[8])} 0`,
        paddingLeft: theme.toRem(theme.spacing[32]),
      },
      ol: {
        listStyleType: "decimal",
        margin: `${theme.toRem(theme.spacing[8])} 0`,
        paddingLeft: theme.toRem(theme.spacing[32]),
      },
      li: {
        marginBottom: theme.toRem(theme.spacing[4]),
        ...theme.typography.body.md,
      },
      blockquote: {
        borderLeft: `${theme.toRem(4)} solid ${theme.color.border.strong}`,
        margin: `0 0 ${theme.toRem(theme.spacing[16])} 0`,
        padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[16])}`,
        color: theme.color.content.weak,
        backgroundColor: theme.color.background.defaultHover,
        borderRadius: `0 ${theme.toRem(theme.border.radius.sm)} ${theme.toRem(theme.border.radius.sm)} 0`,
      },

      ...styleSlots?.content,
    },

    [`.${RichTextClasses.floatingToolbar}`]: {
      position: "absolute",
      zIndex: theme.zIndex.dynamic,

      ...styleSlots?.floatingToolbar,
    },

    [`.${RichTextClasses.linkInsertToolbar}`]: {
      ...styleSlots?.linkInsertToolbar,
    },
    [`.${RichTextClasses.linkEditToolbar}`]: {
      ...styleSlots?.linkEditToolbar,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledRichText = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<RichTextProps>((props) => generateStyles(props));
